INSERT INTO publicacoes (id, usuario_id, conteudo, tema, imagem_url, data_publicacao) VALUES
  (2001, 1001, 'Bem-vinde ao Lindr! 🏳️‍🌈 Aqui o respeito vem primeiro. Leia as regras da comunidade, denuncie qualquer comportamento abusivo e aproveite para fazer novas amizades.', 'Avisos', 'img/demo/arco.svg', DATE_SUB(NOW(), INTERVAL 43000 MINUTE)),
  (2002, 1002, 'Terminei Hollow Knight pela terceira vez e ainda choro no final. Indiquem jogos indie com trilha sonora tão boa quanto!', 'Jogos', 'img/demo/controle.svg', DATE_SUB(NOW(), INTERVAL 380 MINUTE)),
  (2003, 1002, 'Recomendações de livros com personagens LGBTQIA+ escritos com carinho? Estou montando minha lista de leitura de novembro 📚', 'Livros', 'img/demo/livros.svg', DATE_SUB(NOW(), INTERVAL 1450 MINUTE)),
  (2004, 1002, 'Playlist de domingo: Liniker, Pabllo Vittar, Gal Costa e um pouco de Mitski. Alguma sugestão para completar?', 'Música', NULL, DATE_SUB(NOW(), INTERVAL 4300 MINUTE)),
  (2005, 1002, 'Quem aqui joga D&D ou Tormenta? Quero entrar numa mesa nova e aceito ser a clériga do grupo!', 'RPG', 'img/demo/dados.svg', DATE_SUB(NOW(), INTERVAL 9800 MINUTE)),
  (2006, 1003, 'Depois de 3 horas depurando, descobri que o bug era um ponto e vírgula. A vida de dev é isso.', 'Programação', NULL, DATE_SUB(NOW(), INTERVAL 210 MINUTE)),
  (2007, 1003, 'Alguém mais viciado em Balatro? Preciso de ajuda, é bom demais.', 'Jogos', 'img/demo/controle.svg', DATE_SUB(NOW(), INTERVAL 5600 MINUTE)),
  (2008, 1004, 'Hoje na aula falamos sobre a Revolta de Stonewall. Nada como ver a turma inteira atenta a uma história que quase nunca é contada.', 'História', NULL, DATE_SUB(NOW(), INTERVAL 720 MINUTE)),
  (2009, 1004, 'Terminei "Torto Arado" e ainda estou processando. Que livro!', 'Livros', 'img/demo/livros.svg', DATE_SUB(NOW(), INTERVAL 7400 MINUTE)),
  (2010, 1005, 'Aceitando jogadoras e jogadores novos na minha mesa de D&D 5e toda quinta à noite em Joinville (ou online!). Iniciantes são muito bem-vindes.', 'RPG', 'img/demo/dados.svg', DATE_SUB(NOW(), INTERVAL 150 MINUTE)),
  (2011, 1005, 'Desenhei a ficha do meu novo personagem: um bardo trans que luta com música. Aceito feedback!', 'Desenho', NULL, DATE_SUB(NOW(), INTERVAL 11200 MINUTE)),
  (2012, 1006, 'Luz dourada em Blumenau hoje no fim da tarde. Foto feita só com o celular!', 'Fotografia', 'img/demo/cidade.svg', DATE_SUB(NOW(), INTERVAL 95 MINUTE)),
  (2013, 1006, 'Adotei uma gatinha de rua e ela já dominou a casa inteira. Apresento a Pipoca!', 'Animais', 'img/demo/gato.svg', DATE_SUB(NOW(), INTERVAL 8900 MINUTE)),
  (2014, 1007, 'Testei hoje uma moqueca de banana-da-terra vegana. Ficou melhor que a original, juro. Receita nos comentários se pedirem!', 'Culinária', 'img/demo/prato.svg', DATE_SUB(NOW(), INTERVAL 480 MINUTE)),
  (2015, 1007, 'Horta da varanda: primeiras alfaces nascendo. Pequenas vitórias.', 'Natureza', NULL, DATE_SUB(NOW(), INTERVAL 12600 MINUTE)),
  (2016, 1008, 'Terminei a armadura do meu cosplay de Mitsuri: 40 horas de EVA e muita cola quente!', 'Cosplay', NULL, DATE_SUB(NOW(), INTERVAL 300 MINUTE)),
  (2017, 1008, 'Ilustração do dia: deusa do mar com cabelo de estrelas. Feita no tablet.', 'Arte', NULL, DATE_SUB(NOW(), INTERVAL 6100 MINUTE)),
  (2018, 1009, 'Treino de pernas hoje foi sofrido, mas academia sem julgamento é isso: cada um no seu ritmo.', 'Academia', NULL, DATE_SUB(NOW(), INTERVAL 640 MINUTE)),
  (2019, 1009, 'Domingo de beach tennis em Itajaí. Quem quer jogar semana que vem?', 'Esportes', 'img/demo/praia.svg', DATE_SUB(NOW(), INTERVAL 10300 MINUTE)),
  (2020, 1010, 'Pensamento do dia: cuidar da saúde mental não é luxo, é necessidade.', 'Filosofia', NULL, DATE_SUB(NOW(), INTERVAL 900 MINUTE)),
  (2021, 1010, 'Terminei Heartstopper e preciso de abraço. Alguém para chorar junto?', 'Séries', NULL, DATE_SUB(NOW(), INTERVAL 13500 MINUTE)),
  (2022, 1011, 'Mixei um set novo de house com vocais brasileiros. Quem quer ouvir no próximo encontro?', 'Música', NULL, DATE_SUB(NOW(), INTERVAL 260 MINUTE)),
  (2023, 1011, 'Balneário Camboriú no inverno é outra cidade: calma, vazia e linda.', 'Viagens', 'img/demo/praia.svg', DATE_SUB(NOW(), INTERVAL 9100 MINUTE)),
  (2024, 1012, 'Palestra amanhã sobre IA responsável e viés de gênero. Quem vai? Posso levar mais gente do meu grupo.', 'Tecnologia', NULL, DATE_SUB(NOW(), INTERVAL 1100 MINUTE)),
  (2025, 1012, 'Visibilidade importa: mais mulheres trans em tecnologia significa produtos melhores para todo mundo.', 'Política', NULL, DATE_SUB(NOW(), INTERVAL 15200 MINUTE)),
  (2026, 1013, 'Fim de semana de rodada cheia! Torcendo pelo meu time e respeitando o time dos outros.', 'Futebol', NULL, DATE_SUB(NOW(), INTERVAL 1700 MINUTE)),
  (2027, 1013, 'Churrasco de domingo com a galera do futsal. Ambiente seguro e respeitoso sempre.', 'Esportes', NULL, DATE_SUB(NOW(), INTERVAL 12000 MINUTE)),
  (2028, 1014, 'Mais um sábado cantando no bar. Obrigada a quem apareceu e cantou junto 💜', 'Música', NULL, DATE_SUB(NOW(), INTERVAL 540 MINUTE)),
  (2029, 1014, 'Pintei uma parede do meu quarto de azul-turquesa. Já amo.', 'Arte', NULL, DATE_SUB(NOW(), INTERVAL 14400 MINUTE)),
  (2030, 1015, 'Maratona de filmes de terror dos anos 80 neste fim de semana. Quem topa assistir junto por videochamada?', 'Filmes', NULL, DATE_SUB(NOW(), INTERVAL 800 MINUTE)),
  (2031, 1015, 'Atualizei minha lista de animes favoritos. Spoiler: tem muito slice of life.', 'Anime', NULL, DATE_SUB(NOW(), INTERVAL 16000 MINUTE)),
  (2032, 1016, 'Trilha do fim de semana: 12 km, cachoeira no final e zero sinal de celular. Perfeito!', 'Natureza', 'img/demo/trilha.svg', DATE_SUB(NOW(), INTERVAL 390 MINUTE)),
  (2033, 1016, 'Nascer do sol em Lages: -2°C e a vista compensou cada tremida.', 'Fotografia', NULL, DATE_SUB(NOW(), INTERVAL 8200 MINUTE)),
  (2034, 1017, 'Capítulo 20 terminado do meu novo livro. A protagonista é uma capitã de nave trans e eu amo cada linha.', 'Livros', NULL, DATE_SUB(NOW(), INTERVAL 1900 MINUTE)),
  (2035, 1017, 'Ler Octavia Butler muda a forma como a gente imagina o futuro.', 'Filosofia', NULL, DATE_SUB(NOW(), INTERVAL 17500 MINUTE)),
  (2036, 1018, 'Biblioteca nova no bairro! Sempre que posso, deixo um livro com dedicatória para a próxima pessoa.', 'Livros', 'img/demo/livros.svg', DATE_SUB(NOW(), INTERVAL 1300 MINUTE)),
  (2037, 1018, 'Quebra-cabeça de 2000 peças concluído em duas semanas. Sou muito feliz com pouco.', 'Jogos', NULL, DATE_SUB(NOW(), INTERVAL 9700 MINUTE)),
  (2038, 1019, 'Primeira live de Street Fighter amanhã às 20h. Aceito dicas e zoeira saudável.', 'Jogos', 'img/demo/controle.svg', DATE_SUB(NOW(), INTERVAL 170 MINUTE)),
  (2039, 1019, 'Meu humor depende do ping.', 'Memes', NULL, DATE_SUB(NOW(), INTERVAL 7000 MINUTE)),
  (2040, 1020, 'Direitos não se pedem desculpas. Obrigada a quem tem ido às ruas.', 'Política', NULL, DATE_SUB(NOW(), INTERVAL 2300 MINUTE)),
  (2041, 1020, 'Pão de queijo mineiro na AirFryer. Sim, funciona.', 'Culinária', NULL, DATE_SUB(NOW(), INTERVAL 11800 MINUTE)),
  (2042, 1021, 'Roda de capoeira no domingo, todo mundo é bem-vindo. Trazer pandeiro é opcional.', 'Esportes', NULL, DATE_SUB(NOW(), INTERVAL 3000 MINUTE)),
  (2043, 1021, 'Berimbau no fim do dia: melhor terapia.', 'Música', NULL, DATE_SUB(NOW(), INTERVAL 19000 MINUTE)),
  (2044, 1022, 'Primeira semana de aula de Design: já entrei em crise existencial com tipografia.', 'Desenho', NULL, DATE_SUB(NOW(), INTERVAL 450 MINUTE)),
  (2045, 1022, 'Meu cachorro aprendeu a abrir a porta. Estou preocupada.', 'Animais', NULL, DATE_SUB(NOW(), INTERVAL 6600 MINUTE)),
  (2046, 1023, 'Dica de passeio em Recife: Rua do Bom Jesus, a primeira sinagoga das Américas. História em cada esquina.', 'História', 'img/demo/cidade.svg', DATE_SUB(NOW(), INTERVAL 2700 MINUTE)),
