  (3003, 1018, 'comunidade', 'Clube do Livro Arco-Íris', 'Leituras mensais com autoras e autores LGBTQIA+. Encontros online e presenciais.', 'Livros', NULL, NULL, 0, 'ativo', DATE_SUB(NOW(), INTERVAL 24098 MINUTE)),
