  (3006, 1009, 'comunidade', 'Corpos em Movimento', 'Academia e esportes sem julgamento, para todos os corpos e níveis.', 'Academia', NULL, NULL, 0, 'ativo', DATE_SUB(NOW(), INTERVAL 59629 MINUTE)),
  (3007, 1012, 'comunidade', 'Devs Orgulhosos', 'Comunidade de pessoas LGBTQIA+ na tecnologia: vagas, mentorias e dicas.', 'Programação', NULL, NULL, 0, 'ativo', DATE_SUB(NOW(), INTERVAL 31871 MINUTE)),
  (3008, 1007, 'comunidade', 'Culinária Vegana & Afetiva', 'Receitas vegetais, almoços coletivos e comida como cuidado.', 'Culinária', NULL, NULL, 0, 'ativo', DATE_SUB(NOW(), INTERVAL 58670 MINUTE)),
