  (3010, 1013, 'comunidade', 'Núcleo de Aliados (privada)', 'Aliadas e aliados aprendendo juntos. Só para membros.', 'Aliança', NULL, NULL, 1, 'ativo', DATE_SUB(NOW(), INTERVAL 8465 MINUTE)),
  (3101, 1005, 'evento', 'Noite de Jogos de Tabuleiro', 'Traga seu jogo favorito ou venha aprender novos. Tem lanche coletivo.', NULL, 'Café Dado Duplo, Centro — Criciúma', DATE_ADD(DATE(NOW()), INTERVAL '4 19:00' DAY_MINUTE), 0, 'ativo', DATE_SUB(NOW(), INTERVAL 25634 MINUTE)),
  (3102, 1016, 'evento', 'Piquenique no Parque — Dia de Sol', 'Piquenique coletivo, cada pessoa leva algo. Música, bola e muita conversa.', NULL, 'Parque Ecológico — Criciúma', DATE_ADD(DATE(NOW()), INTERVAL '9 15:00' DAY_MINUTE), 0, 'ativo', DATE_SUB(NOW(), INTERVAL 11077 MINUTE)),
