  (3104, 1010, 'evento', 'Roda de Conversa: Saúde Mental LGBTQIA+', 'Conversa acolhedora e sigilosa, mediada por psicóloga. Entrada gratuita.', NULL, 'Espaço Acolher — Criciúma', DATE_ADD(DATE(NOW()), INTERVAL '2 18:30' DAY_MINUTE), 0, 'ativo', DATE_SUB(NOW(), INTERVAL 25051 MINUTE)),
